import json, pathlib, copy
root = pathlib.Path('C:/lesiteinternetquitue')
d = json.loads((root/'docs/encyclopedia-revision/assignments/history.json').read_text(encoding='utf-8-sig'))
src = {s['id']: copy.deepcopy(s) for s in d['sources']}
out = dict(domain='history', reviewedAt='2026-11-14', sources=[], articles=[], termReviews=[], quizPatches=[], sensitivePoints=[])
def evidence(sid, access, passage, limitation='', url=None):
    s=copy.deepcopy(src[sid])
    if url: s['url']=url
    s.update(access=access, passage=passage, limitation=limitation, verifiedAt='2026-11-14')
    s['reviewEvidence']=[dict(url=s['url'],openedAt='2026-11-14',sections=passage,result='Passages réellement ouverts et lus dans le navigateur web.',supports=passage,access=access)]
    out['sources'].append(s)
def new(sid,title,url,organization,passage,access='excerpt',limitation='',author='',published='s.d.'):
    src[sid]=dict(id=sid,title=title,url=url,organization=organization,author=author,published=published,documentKind='Document de référence')
    evidence(sid,access,passage,limitation)
def section(sid,title,text,refs):
    return dict(id=sid,title=title,paragraphs=text,sourceIds=refs.split())
def diagram(kind,title,nodes,caption,refs):
    return dict(kind=kind,title=title,nodes=[dict(label=l,detail=t) for l,t in nodes],caption=caption,sourceIds=refs.split())
