    out['articles'].append(dict(id=a['id'],fullyRead=True,questions=[q['prompt'] for q in qs],findings=['Tous les champs et toutes les questions associés relus ; les trois paragraphes initiaux ne permettaient pas d’apprendre les réponses.', 'Sources primaires, catalogues et synthèses distingués ; dates de conférence, signature, entrée en vigueur, promulgation et publication séparées.', 'Attributions et incertitudes explicites : aucune légende du Club, du papier de la Déclaration ou d’une origine unique ne devient un fait établi.'],patch=patch,sourceIdsReviewed=ids,visual=dict(status='verified',notes='Diagramme original contrôlable relu contre les passages cités. Aucun visuel photographique reproduit : droits de l’inventaire breton soumis à autorisation ; Fig. 2 de Haimenkou repérée sous CC BY mais téléchargement inexploitable, fichier HTML erroné supprimé. La synthèse existante n’est pas certifiée comme observation.'),quizIdsReviewed=[q['id'] for q in qs],status='ready-for-integration',blockers=[]))

